from pathlib import Path
import json, html
R=Path(__file__).resolve().parent/'assets-v1'
t=json.loads((R/'tokens.json').read_text())
def card(src,title,small=''):
 return f'<article class="asset"><div class="sample"><img src="{src}" alt="{title}" loading="lazy"></div><strong>{title}</strong><small>{small}</small><a href="{src}" download>SVG</a> · <a href="png/{src[:-4]}.png" download>PNG</a></article>'
parts=[]
for folder,title in [('modes','Mode illustrations'),('avatars','Player animals'),('icons','Control symbols'),('panels','Panels and states'),('brand','Brand and decoration'),('backgrounds','Backgrounds')]:
 parts.append(f'<section id="{folder}"><h2>{title}</h2><div class="assets">')
 for f in sorted((R/folder).glob('*.svg')):parts.append(card(f.relative_to(R).as_posix(),f.stem.replace('-',' ')))
 parts.append('</div></section>')
palette=''.join(f'<div class="swatch" style="--c:{c}"><i></i><b>{n}</b><code>{c}</code></div>' for n,c in t['theme'].items())
players=''.join(f'<div class="player"><img src="avatars/{p["animal"]}-badge.svg" alt="{p["animal"]}"><b>{p["slot"]}. {p["animal"]}</b><code>{p["color"]}</code></div>' for p in t['players'])
modes=[('trivia','Вікторина','1–8 гравців','Знання та гарна компанія.'),('millionaire','Мільйонер','1 гравець','П’ятнадцять сходинок до перемоги.'),('imposter','Імпостер','3–8 гравців','Одне таємне слово. Хто не в темі?'),('turf','Битва за поле','2 гравці','Захоплюйте клітинки. Зберіть п’ять у ряд.')]
modecards=''.join(f'<button class="mode {"selected" if i==0 else ""}" data-mode="{m}"><img src="modes/{m}.svg" alt=""><span><b>{n}</b><small>{count}</small><em>{desc}</em></span></button>' for i,(m,n,count,desc) in enumerate(modes))
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TriviTV · Arcade assets v1</title><link rel="stylesheet" href="theme.css"><style>
*{box-sizing:border-box}body{margin:0;background:#eef0f5;color:#1b233f;font:16px/1.5 'Segoe UI',Arial,sans-serif}header,main{max-width:1320px;margin:auto;padding:28px}header{display:flex;align-items:center;justify-content:space-between;gap:20px}h1{font-size:26px;margin:0}header p{margin:3px 0;color:#566078}a{color:#284c78}nav{display:flex;gap:18px;flex-wrap:wrap;margin:18px 0}section{margin:40px 0}h2{font-size:25px}small,code{display:block}.palette,.players{display:grid;gap:15px}.palette{grid-template-columns:repeat(6,1fr)}.swatch{background:white;padding:12px;border-radius:14px}.swatch i{display:block;height:74px;background:var(--c);border:2px solid #1b233f;border-radius:10px;margin-bottom:8px}.swatch b{text-transform:capitalize}.players{grid-template-columns:repeat(8,1fr)}.player{text-align:center;background:white;border-radius:16px;padding:15px 5px}.player img{width:80px;height:80px;display:block;margin:0 auto 8px}.player b{font-size:14px;text-transform:capitalize}.player code{font-size:12px}.assets{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.asset{background:white;padding:15px;border-radius:15px;min-width:0}.asset strong{text-transform:capitalize}.asset small{color:#566078;overflow-wrap:anywhere}.asset a{font-size:13px}.sample{height:174px;display:grid;place-items:center;background:repeating-conic-gradient(#e8ebf2 0% 25%,#f5f6fa 0% 50%) 50% /20px 20px;border-radius:10px;margin-bottom:10px;overflow:hidden}.sample img{max-width:94%;max-height:155px}.asset:has(img[src^="backgrounds"]) .sample img{max-width:100%}.scene{display:grid;grid-template-columns:1fr 1fr;align-items:center;background:#1b233f;color:#f6e7c8;border-radius:22px;padding:25px;gap:20px}.scene img{width:100%;background:linear-gradient(#a88beb33,#1b233f)}.scene a{color:#f5b940}.preview-label{display:flex;justify-content:space-between;gap:12px;align-items:center}.preview-label button{font:inherit;border:1px solid #b6bfd0;background:white;padding:8px 14px;border-radius:8px;cursor:pointer}.demo{position:relative;aspect-ratio:16/9;overflow:hidden;background:url(backgrounds/menu.svg) center/cover;border-radius:24px;border:4px solid #1b233f;box-shadow:0 8px 0 #1b233f26;padding:3%;display:flex;flex-direction:column}.demo .top{display:flex;justify-content:space-between;align-items:center;min-height:10%}.demo .top img{width:22%}.demo .top span{color:#1b233f;font-size:clamp(10px,1.2vw,16px);font-weight:800;letter-spacing:.1em}.mode-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;flex:1;margin:16px 0;min-height:0}.arcade button.mode{display:flex;gap:16px;align-items:center;text-align:left;min-height:0;padding:12px;background:#f6e7c8;border-radius:20px}.mode img{width:clamp(50px,9vw,135px);height:100%;max-height:135px;object-fit:contain}.mode span{display:flex;flex-direction:column}.mode b{font-size:clamp(14px,2.2vw,29px)}.mode small{font-size:clamp(9px,1.2vw,15px);font-weight:700}.mode em{font-size:clamp(8px,1vw,13px);font-style:normal;margin-top:6px;font-weight:400}.arcade .mode.selected{outline:4px solid #f5b940;outline-offset:2px}.demo .bottom{display:flex;justify-content:space-between;align-items:center;gap:15px}.roster{display:flex;gap:5px}.roster img{width:clamp(20px,3.7vw,42px);height:auto}.demo .play{min-width:180px;background:#f5b940}.mini-question{flex:1;display:flex;flex-direction:column;justify-content:center;gap:14px}.mini-question h3{font-size:clamp(18px,2.9vw,38px);line-height:1.15;margin:0}.mini-question .panel{padding:20px}.answers{display:grid;grid-template-columns:1fr 1fr;gap:13px}.answers button{text-align:left}.demo .back-demo{padding:8px 12px;font-size:14px;background:#a88beb}.demo.turf-demo{background-image:url(backgrounds/turf.svg)}.demo.millionaire-demo{background-image:url(backgrounds/millionaire.svg)}.demo.imposter-demo{background-image:url(backgrounds/imposter.svg)}.board{display:grid;grid-template-columns:repeat(5,1fr);gap:5px;width:45%;margin:auto}.board i{display:block;aspect-ratio:1;border:3px solid #1b233f;border-radius:9px;background:#6599d1;box-shadow:0 3px 0 #1b233f}.board i:nth-child(3n){background:#d99b63}.notes{color:#566078}.ladder-preview{float:right;width:25%;display:grid;gap:2px;font-size:10px}.ladder-preview span{background:#1b233f;color:#f6e7c8;padding:1px 6px}.ladder-preview .active{background:#f5b940;color:#1b233f}.private{display:grid;grid-template-columns:repeat(8,1fr);gap:8px}.private img{width:100%}.demo button{font-size:clamp(10px,1.5vw,20px)}.demo .panel{font-size:clamp(10px,1.4vw,18px)}@media(max-width:800px){header{display:block}.assets{grid-template-columns:repeat(2,1fr)}.players{grid-template-columns:repeat(4,1fr)}.palette{grid-template-columns:repeat(3,1fr)}.scene{grid-template-columns:1fr}.demo{padding:2%;border-radius:15px}.mode-grid{gap:9px;margin:8px 0}.arcade button.mode{gap:6px;padding:6px;border-radius:12px}.mode em{display:none}.demo .play{min-width:100px;padding:6px 15px}.demo .bottom{gap:6px}.demo .panel{padding:10px}.mini-question{gap:7px}.answers{gap:7px}.answers button{padding:6px}.private{gap:3px}}
</style><header><div><h1>TriviTV · Playful arcade assets</h1><p>Screenshot palette · whole-animal identities · editable vectors</p></div><a href="../TriviTV-Arcade-Assets-v1.zip" download>Download asset pack ↓</a></header><main><div class="preview-label"><h2>In context</h2><span>Interactive visual sample · no game logic</span></div><div class="demo arcade" id="demo"><div class="top"><img src="brand/wordmark-navy.svg" alt="TriviTV"><span>УКРАЇНСЬКА · ЄВРОПА</span></div><div class="mode-grid">MODECARDS</div><div class="bottom"><div class="roster">ROSTER</div><button class="play" id="play">Грати →</button></div></div><p class="notes">Choose a mode and press Play to inspect its assets together. This is a separate visual sample; the live game has not changed.</p><nav><a href="#palette">Palette</a><a href="#players">Players</a><a href="#modes">Modes</a><a href="#icons">Controls</a><a href="#panels">Panels</a><a href="#backgrounds">Backgrounds</a><a href="manifest.json">Manifest</a></nav><section id="palette"><h2>Screenshot palette</h2><div class="palette">PALETTE</div><p>Theme colors are exact hex values from the reference direction. Cream is a deliberate local surface color, not a yellow filter over the artwork.</p></section><section id="players"><h2>Eight player identities</h2><div class="players">PLAYERS</div><p>One animal, number and color per player. These colors are separate from mode colors. No faces, eyes or expressions.</p></section><section class="scene"><img src="art/party-arena.webp" alt="Original isometric party arena"><div><h2>Party arena</h2><p>Original illustration generated from the supplied style reference. Transparent PNG master and optimized WebP; keep this decorative art away from question text.</p><a href="art/party-arena.png" download>PNG master</a> · <a href="art/party-arena.webp" download>WebP</a></div></section>ASSETS<section><h2>Integration</h2><p>SVG is the editable source. PNG exports are provided for Canva and native tools. Controls use text from your game, not baked-in words. Import <a href="theme.css">theme.css</a> and scope it with <code>.arcade</code>. <a href="README.md">Read usage and provenance</a>.</p></section></main><script>
const home=document.querySelector('#demo').innerHTML;let selected='trivia';const names={trivia:'Вікторина',millionaire:'Мільйонер',imposter:'Імпостер',turf:'Битва за поле'};const animals=['lion','bat','turtle','fox','owl','whale','rabbit','deer'];
function bind(){document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{selected=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(c=>c.classList.toggle('selected',c===b))});document.querySelector('#play').onclick=show;}
function show(){const d=document.querySelector('#demo');d.className='demo arcade '+selected+'-demo';let content='';if(selected==='turf')content='<div class="board">'+Array.from({length:25},()=>'<i></i>').join('')+'</div>';else if(selected==='imposter')content='<div class="panel"><h3>Обговоріть і знайдіть імпостера</h3><p>Обговорення · 01:30</p><div class="private">'+animals.map(a=>'<img src="avatars/'+a+'-badge.svg" alt="'+a+'">').join('')+'</div></div>';else content='<div class="panel">'+(selected==='millionaire'?'<div class="ladder-preview">'+Array.from({length:15},(_,i)=>'<span class="'+(i===7?'active':'')+'">'+(15-i)+' · '+[1000000,500000,250000,125000,64000,32000,16000,8000,4000,2000,1000,500,300,200,100][i].toLocaleString('uk')+'</span>').join('')+'</div>':'')+'<h3>Яка планета найближча до Сонця?</h3></div><div class="answers">'+['Меркурій','Венера','Земля','Марс'].map((v,i)=>'<button>'+String.fromCharCode(65+i)+' · '+v+'</button>').join('')+'</div>';d.innerHTML='<div class="top"><img src="brand/wordmark-cream.svg" alt="TriviTV"><button class="back-demo">← Меню</button></div><div class="mini-question">'+content+'</div><div class="bottom"><strong>'+names[selected]+'</strong><span>Visual sample</span></div>';d.querySelector('.back-demo').onclick=()=>{d.className='demo arcade';d.innerHTML=home;selected='trivia';bind();};d.querySelectorAll('.answers button').forEach((b,i)=>b.onclick=()=>{b.className=i===0?'is-correct':'is-incorrect';b.textContent=(i===0?'✓ ':'× ')+b.textContent;});}
bind();
</script></html>'''
roster=''.join(f'<img src="avatars/{p["animal"]}-badge.svg" alt="Player {p["slot"]}: {p["animal"]}">' for p in t['players'])
for key,val in [('MODECARDS',modecards),('ROSTER',roster),('PALETTE',palette),('PLAYERS',players),('ASSETS',''.join(parts))]:page=page.replace(key,val)
(R/'index.html').write_text(page,encoding='utf8')
print('Built interactive gallery')
